// D38 · Part 0~4 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d38_flow.ts   (소리·데이터는 코드 안에서 합성해요)
//   언어 감지 → 번역의 세 가지 길 → BLEU → 어순 → 부분 출력 통역 → 역번역 확인 → 지연 예산을 장난감 번역기로 한 번에


function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}


// [대체] 번역 모델 대신 '역할 사전' 번역기: 한국어 덩어리마다 (역할, 영어)를 찾아 영어 어순(주어 동사 목적어 장소 시간)으로 다시 늘어놓는다
const LEX: Record<string, [string, string]> = {
  저는: ["S", "I"],
  내일: ["T", "tomorrow"],
  어제: ["T", "yesterday"],
  "다음 주": ["T", "next week"],
  치과에: ["P", "to the dentist"],
  병원에서: ["P", "at the hospital"],
  스케일링을: ["O", "scaling"],
  "가고 싶어요": ["V", "want to go"],
  "받고 싶어요": ["V", "want to get"],
  "사랑니를 뽑았어요": ["V", "had my wisdom tooth pulled"],
};
const EN_ORDER = "SVOPT"; // 영어 어순: 주어(S) 동사(V) 목적어(O) 장소(P) 시간(T)
const SENTS: string[][] = [
  ["저는", "내일", "치과에", "가고 싶어요"],
  ["저는", "어제", "병원에서", "사랑니를 뽑았어요"],
  ["저는", "다음 주", "스케일링을", "받고 싶어요"],
];

function translate(tokens: string[]): string {
  // 덩어리 목록(앞부분만 들어도 됨) → 영어 문장. 아직 못 들은 덩어리는 빠진다
  return tokens
    .map((t) => LEX[t])
    .sort((a, b) => EN_ORDER.indexOf(a[0]) - EN_ORDER.indexOf(b[0]))
    .map((p) => p[1])
    .join(" ");
}


// ── Part 1 · 언어 감지와 섞어 말하기 ──
{
  function scriptCounts(text: string): Record<string, number> {
    // 글자 종류별 개수: 한글 · 일본어 가나 · 한자 · 알파벳 (공백 · 숫자 · 기호는 세지 않는다)
    const n = (re: RegExp): number => (text.match(re) ?? []).length;
    return { hangul: n(/[가-힣]/g), kana: n(/[ぁ-ヿ]/g), han: n(/[一-鿿]/g), latin: n(/[A-Za-z]/g) };
  }

  function hangulRatio(text: string): number {
    // 글자(공백 제외) 가운데 한글의 비율
    const c = scriptCounts(text);
    const total = c.hangul + c.kana + c.han + c.latin;
    return total ? c.hangul / total : 0;
  }

  function detectLang(text: string): Array<[string, number]> {
    // [대체] Whisper의 소리 기반 언어 감지 대신 받아쓴 글의 글자 종류로 [언어, 확률]. 후보 언어 사이에서만 고른다
    const c = scriptCounts(text);
    const score: Record<string, number> = { ko: c.hangul, ja: c.kana + (c.kana ? 0.3 * c.han : 0), zh: c.kana ? 0 : c.han, en: c.latin };
    const tot = Object.values(score).reduce((a, b) => a + b, 0) + 1e-9;
    return Object.entries(score).map(([k, v]): [string, number] => [k, v / tot]).sort((a, b) => b[1] - a[1]);
  }

  const SAMPLES: Record<string, string> = {
    ko: "내일 오후 세 시에 예약하고 싶어요.",
    en: "I would like to book an appointment tomorrow.",
    ja: "明日の午後三時に予約したいです。",
    zh: "我想预约明天下午三点。",
  };
  for (const [lang, text] of Object.entries(SAMPLES)) {
    const p = detectLang(text);
    console.log(`${lang}: 1등 ${p[0][0]} (${(p[0][1] * 100).toFixed(0)}%) · ${text}`);
  }
  const MIX = "내일 스케일링 예약을 cancel하고 싶어요."; // 한국어 문장에 영어 낱말
  const pm = detectLang(MIX);
  const pmEn = pm.find(([k]) => k === "en")![1];
  console.log(`섞인 문장: 1등 ${pm[0][0]} (${(pm[0][1] * 100).toFixed(0)}%) · 영어 비율 ${(pmEn * 100).toFixed(0)}% → 한 언어로 고정해 받아쓰면 영어 낱말이 깨질 수 있어요`);
  const ratios = [hangulRatio("안녕"), hangulRatio("hello"), hangulRatio("안녕 hello"), hangulRatio("")];
  check(
    Object.entries(SAMPLES).every(([k, t]) => detectLang(t)[0][0] === k) && Math.abs(ratios[2] - 2 / 7) < 1e-12 && ratios[0] === 1 && ratios[1] === 0 && ratios[3] === 0 && pm[0][0] === "ko" && pmEn > 0.2,
    "네 언어를 맞히고, 섞인 문장은 한국어가 1등이어도 영어 비율(0.2 넘게)을 알려 줘야 해요.",
  );
}


// ── Part 2 · 번역의 세 가지 길 ──
{
  const P_STT = 0.08;
  const P_MT = 0.1;
  const P_DIRECT = 0.12; // 덩어리 하나가 틀릴 확률(가정한 값): 받아쓰기 · 글 번역 · 소리 직접 번역
  const PATHS = ["글 → 글", "소리 → 글(직접)", "받아쓰기 + 번역(Cascade)"];
  const SEC: Record<string, number> = { "글 → 글": 0.4, "소리 → 글(직접)": 0.5, "받아쓰기 + 번역(Cascade)": 0.3 + 0.4 }; // 걸리는 시간(초, 가정한 값)
  const EXPECT: Record<string, number> = { "글 → 글": 1 - P_MT, "소리 → 글(직접)": 1 - P_DIRECT, "받아쓰기 + 번역(Cascade)": (1 - P_STT) * (1 - P_MT) }; // 단계가 늘면 정확도는 곱해서 줄어든다
  const rnd = mulberry32(0);
  const tokens = SENTS.flat();
  const N = 500; // 같은 문장들을 500번 번역해 본다
  const ok: Record<string, number> = { "글 → 글": 0, "소리 → 글(직접)": 0, "받아쓰기 + 번역(Cascade)": 0 };
  for (let i = 0; i < N; i++) {
    for (let t = 0; t < tokens.length; t++) {
      if (rnd() > P_MT) ok["글 → 글"]++;
      if (rnd() > P_DIRECT) ok["소리 → 글(직접)"]++;
      if (rnd() > P_STT && rnd() > P_MT) ok["받아쓰기 + 번역(Cascade)"]++;
    }
  }
  const acc: Record<string, number> = {};
  for (const k of PATHS) {
    acc[k] = ok[k] / (N * tokens.length);
    console.log(`${k} 정확한 덩어리 ${(acc[k] * 100).toFixed(1)}% (이론 ${(EXPECT[k] * 100).toFixed(1)}%) · ${SEC[k].toFixed(1)}초`);
  }
  console.log("Cascade는 중간에 '글'이 남아 용어 검사 · 기록이 쉽고, 직접 번역은 단계가 하나 적어 빠릅니다.");
  check(
    translate(SENTS[0]) === "I want to go to the dentist tomorrow" &&
      PATHS.every((k) => Math.abs(acc[k] - EXPECT[k]) < 0.03) &&
      acc["글 → 글"] > acc["소리 → 글(직접)"] &&
      acc["소리 → 글(직접)"] > acc["받아쓰기 + 번역(Cascade)"] &&
      SEC["소리 → 글(직접)"] < SEC["받아쓰기 + 번역(Cascade)"],
    "정확도는 단계마다 곱해져 Cascade가 가장 낮고, 직접 번역은 단계가 적어 더 빨라야 해요.",
  );
}


// ── Part 2-1 · 번역 품질 재기: BLEU · chrF · 용어 정확도 ──
{
  function ngrams(tokens: string[], n: number): string[] {
    const out: string[] = [];
    for (let i = 0; i + n <= tokens.length; i++) out.push(tokens.slice(i, i + n).join("\u0000"));
    return out;
  }

  function ngramStats(hyp: string[], ref: string[], n: number): [number, number] {
    // [참조에도 있는 n-gram 수, 번역의 n-gram 수]. 같은 n-gram은 참조에 나온 횟수까지만 인정
    const r = new Map<string, number>();
    for (const g of ngrams(ref, n)) r.set(g, (r.get(g) ?? 0) + 1);
    const h = ngrams(hyp, n);
    let match = 0;
    for (const g of h) {
      if ((r.get(g) ?? 0) > 0) {
        match++;
        r.set(g, (r.get(g) as number) - 1);
      }
    }
    return [match, h.length];
  }

  function brevityPenalty(hypLen: number, refLen: number): number {
    // 짧은 번역 벌점: 참조보다 짧으면 exp(1 - 참조 길이 / 번역 길이), 아니면 1
    return hypLen >= refLen ? 1 : Math.exp(1 - refLen / hypLen);
  }

  function bleu(hyp: string, ref: string, maxN: number = 4): number {
    const h = hyp.split(" ");
    const r = ref.split(" ");
    let sum = 0;
    for (let n = 1; n <= maxN; n++) {
      const [m, t] = ngramStats(h, r, n);
      sum += Math.log(n > 1 ? (m + 1) / (t + 1) : Math.max(m, 1e-9) / Math.max(t, 1)); // 2-gram부터 +1 보정
    }
    return brevityPenalty(h.length, r.length) * Math.exp(sum / maxN);
  }

  function chrf(hyp: string, ref: string, maxN: number = 6, beta: number = 2): number {
    // 글자 n-gram의 정밀도 · 재현율을 평균 낸 F점수(재현율에 beta배 비중)
    const h = [...hyp.replaceAll(" ", "")];
    const r = [...ref.replaceAll(" ", "")];
    let ps = 0;
    let rs = 0;
    for (let n = 1; n <= maxN; n++) {
      const [m, t] = ngramStats(h, r, n);
      const tr = ngramStats(r, r, n)[1];
      ps += t ? m / t : 0;
      rs += tr ? m / tr : 0;
    }
    const p = ps / maxN;
    const rc = rs / maxN;
    return p + rc === 0 ? 0 : ((1 + beta ** 2) * p * rc) / (beta ** 2 * p + rc);
  }

  function termScore(hyp: string, groups: string[][]): number {
    // 꼭 있어야 할 낱말 묶음 가운데 번역에 들어 있는 비율(묶음마다 하나라도 있으면 통과)
    return groups.filter((g) => g.some((w) => hyp.toLowerCase().includes(w))).length / groups.length;
  }

  const REF = "I want to go to the dentist tomorrow";
  const HYPS: Record<string, string> = { 완벽: REF, "용어 오류(내일 → 어제)": "I want to go to the dentist yesterday", "맞는 바꿔 말하기": "I would like to visit a dentist tomorrow" };
  const TERMS = [["tomorrow"], ["dentist"]];
  console.log("번역 | BLEU | chrF | 용어");
  const S: Record<string, number[]> = {};
  for (const [name, hyp] of Object.entries(HYPS)) {
    S[name] = [bleu(hyp, REF), chrf(hyp, REF), termScore(hyp, TERMS)];
    console.log(`${name} | ${S[name][0].toFixed(2)} | ${S[name][1].toFixed(2)} | ${S[name][2].toFixed(2)}`);
  }
  check(
    Math.abs(brevityPenalty(5, 10) - Math.exp(-1)) < 1e-9 &&
      brevityPenalty(10, 10) === 1 &&
      brevityPenalty(12, 10) === 1 &&
      ngramStats("the cat sat".split(" "), "the cat sat on the mat".split(" "), 1).join() === "3,3" &&
      Math.abs(S["완벽"][0] - 1) < 1e-9 &&
      Math.abs(S["완벽"][1] - 1) < 1e-9 &&
      S["용어 오류(내일 → 어제)"][0] > 0.6 &&
      S["용어 오류(내일 → 어제)"][2] === 0.5 &&
      S["맞는 바꿔 말하기"][0] < 0.4 &&
      S["맞는 바꿔 말하기"][2] === 1,
    "BLEU는 용어 하나가 틀려도 높고, 맞는 바꿔 말하기에는 낮아요. 그래서 용어 정확도를 따로 재야 해요.",
  );
}


// ── Part 3 · 어순과 통역: 동사를 기다려야 한다 ──
{
  function inversions(seq: number[]): number {
    // 뒤집힌 짝의 수: 정렬에서 서로 엇갈리는 (앞, 뒤) 쌍
    let c = 0;
    for (let i = 0; i < seq.length; i++) for (let j = i + 1; j < seq.length; j++) if (seq[i] > seq[j]) c++;
    return c;
  }

  function need(srcOfTgt: number[]): number[] {
    // 목표 덩어리를 차례로 내보낼 때, 각각 원문을 몇 덩어리까지 들어야 하나(앞에서 이미 들은 만큼은 유지)
    let m = 0;
    return srcOfTgt.map((i) => (m = Math.max(m, i + 1)));
  }

  function koToEn(tokens: string[]): number[] {
    // 영어로 내보내는 순서에서 각 덩어리의 한국어 위치
    return tokens.map((_, i) => i).sort((a, b) => EN_ORDER.indexOf(LEX[tokens[a]][0]) - EN_ORDER.indexOf(LEX[tokens[b]][0]));
  }

  function meanLag(srcOfTgt: number[]): number {
    // 목표 덩어리 j를 말할 때 그 시각에 '이미 말한 양'보다 원문을 몇 덩어리 더 들어야 하나의 평균
    const n = need(srcOfTgt);
    return n.reduce((s, v, j) => s + (v - (j + 1)), 0) / n.length;
  }

  for (const s of SENTS) {
    const order = koToEn(s);
    console.log(`${s.join(" ")}\n   영어 순서로 읽는 한국어 위치 [${order}] · 필요한 원문 덩어리 [${need(order)}] · 평균 기다림 ${meanLag(order).toFixed(2)}덩어리 · 뒤집힌 짝 ${inversions(order)}개`);
  }
  const same = [0, 1, 2, 3]; // 어순이 같은 언어 쌍(예: 영어 ↔ 스페인어): 차례대로 옮기면 된다
  console.log(`어순이 같은 쌍: 필요한 원문 덩어리 [${need(same)}] · 평균 기다림 ${meanLag(same).toFixed(2)}덩어리`);
  const verbPos = SENTS.map((s) => koToEn(s).indexOf(s.length - 1)); // 한국어 동사(맨 끝)가 영어 순서에서 몇 번째로 나가나
  check(
    inversions([0, 3, 2, 1]) === 3 &&
      need([0, 3, 2, 1]).join() === "1,4,4,4" &&
      meanLag(same) === 0 &&
      SENTS.every((s) => meanLag(koToEn(s)) > 0) &&
      SENTS.every((s, k) => verbPos[k] === 1 && need(koToEn(s))[1] === s.length),
    "영어는 동사가 둘째로 나가는데 한국어 동사는 맨 끝이라, 동사를 말하려면 문장이 끝나야 해요.",
  );
}


// ── Part 3 · 문장 단위 vs 부분 출력 통역 ──
{
  const SPEC = 0.6;
  const MT_SEC = 0.3; // 덩어리 하나 말하는 시간 · 번역 한 번에 걸리는 시간(초, 가정한 값)

  function commonPrefixLen(a: string[], b: string[]): number {
    // 두 번역이 맨 앞부터 똑같은 낱말 수
    let n = 0;
    while (n < Math.min(a.length, b.length) && a[n] === b[n]) n++;
    return n;
  }

  function run(tokens: string[], policy: string): { first: number | null; flicker: number; final: string[] } {
    // 덩어리를 하나씩 들을 때마다 번역하고, 정책에 따라 화면(shown)을 바꾼다
    let shown: string[] = [];
    let prev: string[] = [];
    let flicker = 0;
    let first: number | null = null;
    for (let k = 1; k <= tokens.length; k++) {
      const t = k * SPEC + MT_SEC;
      const hyp = translate(tokens.slice(0, k)).split(" ");
      const last = k === tokens.length;
      let next: string[];
      if (policy === "sentence") next = last ? hyp : shown; // 문장이 끝나야 번역
      else if (policy === "partial") next = hyp; // 매번 최신 번역으로 바꿔 보여 줌
      else {
        const stable = last ? hyp : hyp.slice(0, commonPrefixLen(prev, hyp)); // 직전 번역과 같은 앞부분만 확정
        next = stable.length > shown.length && stable.slice(0, shown.length).join(" ") === shown.join(" ") ? stable : shown;
      }
      flicker += shown.length - commonPrefixLen(shown, next); // 이미 보여 준 낱말이 바뀐 수
      shown = next;
      prev = hyp;
      if (shown.length && first === null) first = t;
    }
    return { first, flicker, final: shown };
  }

  const RES: Record<string, { first: number; flicker: number; ok: boolean }> = {};
  for (const [policy, name] of [["sentence", "문장 단위"], ["partial", "부분 출력(매번 다시)"], ["stable", "안정된 앞부분만"]]) {
    const r = SENTS.map((s) => run(s, policy));
    RES[policy] = {
      first: r.reduce((a, x) => a + (x.first as number), 0) / r.length,
      flicker: r.reduce((a, x) => a + x.flicker, 0),
      ok: r.every((x, i) => x.final.join(" ") === translate(SENTS[i])),
    };
    console.log(`${name} 첫 낱말이 나오기까지 ${RES[policy].first.toFixed(1)}초 · 깜빡임(바뀐 낱말) ${RES[policy].flicker}개`);
  }
  check(
    commonPrefixLen(["a", "b", "c"], ["a", "b", "d"]) === 2 &&
      commonPrefixLen(["a"], ["b"]) === 0 &&
      RES.sentence.flicker === 0 &&
      RES.stable.flicker === 0 &&
      RES.partial.flicker > 0 &&
      RES.partial.first < RES.stable.first &&
      RES.stable.first <= RES.sentence.first &&
      Object.values(RES).every((v) => v.ok),
    "부분 출력은 빠르지만 깜빡이고, 문장 단위는 깜빡이지 않지만 느려요. 안정된 앞부분만 확정하면 그 중간이에요.",
  );
}


// ── Part 4 · 역번역 확인 ──
{
  // [대체] 번역 모델 대신 구절 사전. 앞(한→영)과 뒤(영→한) 사전에 일부러 틀린 항목을 넣어 둔다
  const FWD: Record<string, string> = { 하루에: "per week", "한 번": "once", 약을: "the medicine", 먹어요: "take", 식후에: "before meals", 매일: "every day", "두 알": "two pills", 마셔요: "drink", 물을: "water" };
  const BWD: Record<string, string> = { "per week": "일주일에", once: "한 번", "the medicine": "약을", take: "먹어요", "before meals": "식후에", "every day": "매일", "two pills": "두 알", drink: "마셔요", water: "물을" };
  // 틀린 항목 ① 하루에 → per week (뒤에서 일주일에로 되돌아와 들통남)  ② 식후에 → before meals (뒤에서도 식후에로 돌아와 못 잡음)

  const translateWith = (lex: Record<string, string>, phrases: string[]): string[] => phrases.map((p) => lex[p]);

  function similarity(a: string[], b: string[]): number {
    // 덩어리 집합의 F1: 원래 말과 되돌린 말이 얼마나 같은가
    const sa = new Set(a);
    const sb = new Set(b);
    const inter = [...sa].filter((x) => sb.has(x)).length;
    return inter === 0 ? 0 : (2 * inter) / (sa.size + sb.size);
  }

  const CASES: string[][] = [["하루에", "한 번", "약을", "먹어요"], ["매일", "물을", "마셔요"], ["식후에", "약을", "먹어요"], ["매일", "두 알", "먹어요"]];
  const TH = 0.8;
  const flagged: boolean[] = [];
  for (const src of CASES) {
    const en = translateWith(FWD, src);
    const back = translateWith(BWD, en);
    const sim = similarity(src, back);
    flagged.push(sim < TH);
    console.log(`${src.join(" ")} → ${en.join(" ")} → ${back.join(" ")} 유사도 ${sim.toFixed(2)} ${sim < TH ? "확인 필요" : "OK"}`);
  }
  check(
    flagged.join() === "true,false,false,false" && similarity(["a", "b"], ["a", "b"]) === 1,
    "역번역은 되돌아온 말이 달라진 번역(하루에 → 일주일에)만 잡아요. 앞뒤가 같이 틀린 번역(식후에 → before meals)은 못 잡는다는 한계도 기억하세요.",
  );
}


// ── Part 4 · 통역 지연 예산 ──
{
  const rng = mulberry32(4);
  const uni = (lo: number, hi: number): number => lo + (hi - lo) * rng();
  const BUDGET = 2.5; // 귀-입 지연 예산(초): 손님 말이 끝난 뒤 통역 소리가 시작되기까지
  const E = 0.7; // 말이 끝났다고 판단하는 데 기다리는 시간(끝점)

  function stages(dur: number, words: number): { stt: number; mt: number; tts: number } {
    // [대체] 실제 모델 대신 길이에 비례하는 가정한 처리 시간(초)
    return { stt: 0.2 + 0.15 * dur, mt: 0.15 + 0.1 * words, tts: 0.3 };
  }

  function sequential(dur: number, words: number): number {
    const s = stages(dur, words);
    return E + s.stt + s.mt + s.tts; // 말이 끝난 뒤에 받아쓰기 → 번역 → 합성을 차례로
  }

  function streaming(dur: number, words: number): number {
    const s = stages(dur, words);
    return E + 0.1 + 0.05 * dur + (0.15 + 0.1 * 2) + s.tts; // 말하는 동안 받아쓰기·번역을 미리 진행: 끝난 뒤엔 마지막 덩어리만
  }

  function pct(a: number[], p: number): number {
    // 백분위수(선형 보간)
    const s = [...a].sort((x, y) => x - y);
    const k = ((s.length - 1) * p) / 100;
    const lo = Math.floor(k);
    return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
  }

  const turns: Array<[number, number]> = Array.from({ length: 40 }, (): [number, number] => [uni(2, 6), 4 + Math.floor(uni(0, 10))]);
  const seq = turns.map(([d, w]) => sequential(d, w));
  const stm = turns.map(([d, w]) => streaming(d, w));
  const over = (a: number[]): number => a.filter((v) => v > BUDGET).length / a.length;
  console.log(`순차 처리 p50 ${pct(seq, 50).toFixed(2)}초 · p95 ${pct(seq, 95).toFixed(2)}초 · 예산 초과 ${(over(seq) * 100).toFixed(0)}%`);
  console.log(`스트리밍 p50 ${pct(stm, 50).toFixed(2)}초 · p95 ${pct(stm, 95).toFixed(2)}초 · 예산 초과 ${(over(stm) * 100).toFixed(0)}%`);
  // 한 번에 한 턴씩만 처리(GPU 자물쇠): 말이 몰리면 줄을 서서 기다린다
  let t = 0;
  const arrive = turns.map(() => (t += uni(1, 4)));
  let free = 0;
  const waits: number[] = [];
  turns.forEach(([d, w], i) => {
    const s = stages(d, w);
    const start = Math.max(arrive[i] + E, free);
    waits.push(start - (arrive[i] + E));
    free = start + s.stt + s.mt + s.tts;
  });
  console.log(`줄 서기: 기다린 턴 ${waits.filter((x) => x > 1e-9).length}/${waits.length} · 가장 오래 ${Math.max(...waits).toFixed(2)}초`);
  const s0 = stages(4, 8);
  check(
    Math.abs(sequential(4, 8) - (E + s0.stt + s0.mt + s0.tts)) < 1e-9 && pct(stm, 95) < pct(seq, 95) && over(stm) <= over(seq) && Math.min(...waits) >= 0,
    "지연은 단계 시간의 합이고, 스트리밍은 말하는 동안 미리 처리해 더 짧아요.",
  );
}

langid.typescript:
// D38 · Part 1 · 언어 감지와 섞어 말하기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d38_langid.ts   (소리·데이터는 코드 안에서 합성해요)
//   글자 종류 비율로 언어를 감지하고 한 문장 안의 섞임을 알아채기


function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}


function scriptCounts(text: string): Record<string, number> {
  // 글자 종류별 개수: 한글 · 일본어 가나 · 한자 · 알파벳 (공백 · 숫자 · 기호는 세지 않는다)
  const n = (re: RegExp): number => (text.match(re) ?? []).length;
  return { hangul: n(/[가-힣]/g), kana: n(/[ぁ-ヿ]/g), han: n(/[一-鿿]/g), latin: n(/[A-Za-z]/g) };
}

function hangulRatio(text: string): number {
  // 글자(공백 제외) 가운데 한글의 비율
  const c = scriptCounts(text);
  const total = c.hangul + c.kana + c.han + c.latin;
  return total ? c.hangul / total : 0;
}

function detectLang(text: string): Array<[string, number]> {
  // [대체] Whisper의 소리 기반 언어 감지 대신 받아쓴 글의 글자 종류로 [언어, 확률]. 후보 언어 사이에서만 고른다
  const c = scriptCounts(text);
  const score: Record<string, number> = { ko: c.hangul, ja: c.kana + (c.kana ? 0.3 * c.han : 0), zh: c.kana ? 0 : c.han, en: c.latin };
  const tot = Object.values(score).reduce((a, b) => a + b, 0) + 1e-9;
  return Object.entries(score).map(([k, v]): [string, number] => [k, v / tot]).sort((a, b) => b[1] - a[1]);
}

const SAMPLES: Record<string, string> = {
  ko: "내일 오후 세 시에 예약하고 싶어요.",
  en: "I would like to book an appointment tomorrow.",
  ja: "明日の午後三時に予約したいです。",
  zh: "我想预约明天下午三点。",
};
for (const [lang, text] of Object.entries(SAMPLES)) {
  const p = detectLang(text);
  console.log(`${lang}: 1등 ${p[0][0]} (${(p[0][1] * 100).toFixed(0)}%) · ${text}`);
}
const MIX = "내일 스케일링 예약을 cancel하고 싶어요."; // 한국어 문장에 영어 낱말
const pm = detectLang(MIX);
const pmEn = pm.find(([k]) => k === "en")![1];
console.log(`섞인 문장: 1등 ${pm[0][0]} (${(pm[0][1] * 100).toFixed(0)}%) · 영어 비율 ${(pmEn * 100).toFixed(0)}% → 한 언어로 고정해 받아쓰면 영어 낱말이 깨질 수 있어요`);
const ratios = [hangulRatio("안녕"), hangulRatio("hello"), hangulRatio("안녕 hello"), hangulRatio("")];
check(
  Object.entries(SAMPLES).every(([k, t]) => detectLang(t)[0][0] === k) && Math.abs(ratios[2] - 2 / 7) < 1e-12 && ratios[0] === 1 && ratios[1] === 0 && ratios[3] === 0 && pm[0][0] === "ko" && pmEn > 0.2,
  "네 언어를 맞히고, 섞인 문장은 한국어가 1등이어도 영어 비율(0.2 넘게)을 알려 줘야 해요.",
);

paths.typescript:
// D38 · Part 2 · 번역의 세 가지 길 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d38_paths.ts   (소리·데이터는 코드 안에서 합성해요)
//   글 → 글, 소리 → 글(직접), 받아쓰기 + 번역(Cascade)의 품질과 지연 비교


function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}


// [대체] 번역 모델 대신 '역할 사전' 번역기: 한국어 덩어리마다 (역할, 영어)를 찾아 영어 어순(주어 동사 목적어 장소 시간)으로 다시 늘어놓는다
const LEX: Record<string, [string, string]> = {
  저는: ["S", "I"],
  내일: ["T", "tomorrow"],
  어제: ["T", "yesterday"],
  "다음 주": ["T", "next week"],
  치과에: ["P", "to the dentist"],
  병원에서: ["P", "at the hospital"],
  스케일링을: ["O", "scaling"],
  "가고 싶어요": ["V", "want to go"],
  "받고 싶어요": ["V", "want to get"],
  "사랑니를 뽑았어요": ["V", "had my wisdom tooth pulled"],
};
const EN_ORDER = "SVOPT"; // 영어 어순: 주어(S) 동사(V) 목적어(O) 장소(P) 시간(T)
const SENTS: string[][] = [
  ["저는", "내일", "치과에", "가고 싶어요"],
  ["저는", "어제", "병원에서", "사랑니를 뽑았어요"],
  ["저는", "다음 주", "스케일링을", "받고 싶어요"],
];

function translate(tokens: string[]): string {
  // 덩어리 목록(앞부분만 들어도 됨) → 영어 문장. 아직 못 들은 덩어리는 빠진다
  return tokens
    .map((t) => LEX[t])
    .sort((a, b) => EN_ORDER.indexOf(a[0]) - EN_ORDER.indexOf(b[0]))
    .map((p) => p[1])
    .join(" ");
}


const P_STT = 0.08;
const P_MT = 0.1;
const P_DIRECT = 0.12; // 덩어리 하나가 틀릴 확률(가정한 값): 받아쓰기 · 글 번역 · 소리 직접 번역
const PATHS = ["글 → 글", "소리 → 글(직접)", "받아쓰기 + 번역(Cascade)"];
const SEC: Record<string, number> = { "글 → 글": 0.4, "소리 → 글(직접)": 0.5, "받아쓰기 + 번역(Cascade)": 0.3 + 0.4 }; // 걸리는 시간(초, 가정한 값)
const EXPECT: Record<string, number> = { "글 → 글": 1 - P_MT, "소리 → 글(직접)": 1 - P_DIRECT, "받아쓰기 + 번역(Cascade)": (1 - P_STT) * (1 - P_MT) }; // 단계가 늘면 정확도는 곱해서 줄어든다
const rnd = mulberry32(0);
const tokens = SENTS.flat();
const N = 500; // 같은 문장들을 500번 번역해 본다
const ok: Record<string, number> = { "글 → 글": 0, "소리 → 글(직접)": 0, "받아쓰기 + 번역(Cascade)": 0 };
for (let i = 0; i < N; i++) {
  for (let t = 0; t < tokens.length; t++) {
    if (rnd() > P_MT) ok["글 → 글"]++;
    if (rnd() > P_DIRECT) ok["소리 → 글(직접)"]++;
    if (rnd() > P_STT && rnd() > P_MT) ok["받아쓰기 + 번역(Cascade)"]++;
  }
}
const acc: Record<string, number> = {};
for (const k of PATHS) {
  acc[k] = ok[k] / (N * tokens.length);
  console.log(`${k} 정확한 덩어리 ${(acc[k] * 100).toFixed(1)}% (이론 ${(EXPECT[k] * 100).toFixed(1)}%) · ${SEC[k].toFixed(1)}초`);
}
console.log("Cascade는 중간에 '글'이 남아 용어 검사 · 기록이 쉽고, 직접 번역은 단계가 하나 적어 빠릅니다.");
check(
  translate(SENTS[0]) === "I want to go to the dentist tomorrow" &&
    PATHS.every((k) => Math.abs(acc[k] - EXPECT[k]) < 0.03) &&
    acc["글 → 글"] > acc["소리 → 글(직접)"] &&
    acc["소리 → 글(직접)"] > acc["받아쓰기 + 번역(Cascade)"] &&
    SEC["소리 → 글(직접)"] < SEC["받아쓰기 + 번역(Cascade)"],
  "정확도는 단계마다 곱해져 Cascade가 가장 낮고, 직접 번역은 단계가 적어 더 빨라야 해요.",
);

bleu.python:
# D38 · Part 2-1 · 번역 품질 재기: BLEU · chrF · 용어 정확도 — 단독 실행 완성 코드 (Python 3.11)
# pip install numpy==2.4.6
# 실행: python d38_bleu.py   (소리·데이터는 코드 안에서 합성해요 · 인터넷·GPU·마이크·API 키 불필요)
#   n-gram 정밀도 · 짧은 번역 벌점 · BLEU · chrF를 직접 계산하고 BLEU가 놓치는 용어 오류 잡기


import math
import re

import numpy as np


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def ngrams(tokens: list, n: int) -> list:
    return [tuple(tokens[i:i + n]) for i in range(len(tokens) - n + 1)]


def ngram_stats(hyp: list, ref: list, n: int) -> tuple:
    """(참조에도 있는 n-gram 수, 번역의 n-gram 수). 같은 n-gram은 참조에 나온 횟수까지만 인정."""
    h, r = ngrams(hyp, n), {}
    for g in ngrams(ref, n):
        r[g] = r.get(g, 0) + 1
    match = 0
    for g in h:
        if r.get(g, 0) > 0:
            match += 1
            r[g] -= 1
    return match, len(h)


def brevity_penalty(hyp_len: int, ref_len: int) -> float:
    """짧은 번역 벌점: 참조보다 짧으면 exp(1 - 참조 길이 / 번역 길이), 아니면 1."""
    return 1.0 if hyp_len >= ref_len else math.exp(1 - ref_len / hyp_len)


def bleu(hyp: str, ref: str, max_n: int = 4) -> float:
    h, r = hyp.split(), ref.split()
    logs = []
    for n in range(1, max_n + 1):
        m, t = ngram_stats(h, r, n)
        logs.append(math.log(((m + 1) / (t + 1)) if n > 1 else max(m, 1e-9) / max(t, 1)))     # 2-gram부터 +1 보정
    return brevity_penalty(len(h), len(r)) * math.exp(sum(logs) / max_n)


def chrf(hyp: str, ref: str, max_n: int = 6, beta: float = 2.0) -> float:
    """글자 n-gram의 정밀도 · 재현율을 평균 낸 F점수(재현율에 beta배 비중)."""
    h, r = hyp.replace(" ", ""), ref.replace(" ", "")
    ps, rs = [], []
    for n in range(1, max_n + 1):
        m, t = ngram_stats(list(h), list(r), n)
        _, tr = ngram_stats(list(r), list(r), n)
        ps.append(m / t if t else 0.0)
        rs.append(m / tr if tr else 0.0)
    p, rc = sum(ps) / max_n, sum(rs) / max_n
    return 0.0 if p + rc == 0 else (1 + beta ** 2) * p * rc / (beta ** 2 * p + rc)


def term_score(hyp: str, groups: list) -> float:
    """꼭 있어야 할 낱말 묶음 가운데 번역에 들어 있는 비율(묶음마다 하나라도 있으면 통과)."""
    return sum(any(w in hyp.lower() for w in g) for g in groups) / len(groups)


REF = "I want to go to the dentist tomorrow"
