bleu.typescript:
// D38 · Part 2-1 · 번역 품질 재기: BLEU · chrF · 용어 정확도 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d38_bleu.ts   (소리·데이터는 코드 안에서 합성해요)
//   n-gram 정밀도 · 짧은 번역 벌점 · BLEU · chrF를 직접 계산하고 BLEU가 놓치는 용어 오류 잡기


function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}


function ngrams(tokens: string[], n: number): string[] {
  const out: string[] = [];
  for (let i = 0; i + n <= tokens.length; i++) out.push(tokens.slice(i, i + n).join("\u0000"));
  return out;
}

function ngramStats(hyp: string[], ref: string[], n: number): [number, number] {
  // [참조에도 있는 n-gram 수, 번역의 n-gram 수]. 같은 n-gram은 참조에 나온 횟수까지만 인정
  const r = new Map<string, number>();
  for (const g of ngrams(ref, n)) r.set(g, (r.get(g) ?? 0) + 1);
  const h = ngrams(hyp, n);
  let match = 0;
  for (const g of h) {
    if ((r.get(g) ?? 0) > 0) {
      match++;
      r.set(g, (r.get(g) as number) - 1);
    }
  }
  return [match, h.length];
}

function brevityPenalty(hypLen: number, refLen: number): number {
  // 짧은 번역 벌점: 참조보다 짧으면 exp(1 - 참조 길이 / 번역 길이), 아니면 1
  return hypLen >= refLen ? 1 : Math.exp(1 - refLen / hypLen);
}

function bleu(hyp: string, ref: string, maxN: number = 4): number {
  const h = hyp.split(" ");
  const r = ref.split(" ");
  let sum = 0;
  for (let n = 1; n <= maxN; n++) {
    const [m, t] = ngramStats(h, r, n);
    sum += Math.log(n > 1 ? (m + 1) / (t + 1) : Math.max(m, 1e-9) / Math.max(t, 1)); // 2-gram부터 +1 보정
  }
  return brevityPenalty(h.length, r.length) * Math.exp(sum / maxN);
}

function chrf(hyp: string, ref: string, maxN: number = 6, beta: number = 2): number {
  // 글자 n-gram의 정밀도 · 재현율을 평균 낸 F점수(재현율에 beta배 비중)
  const h = [...hyp.replaceAll(" ", "")];
  const r = [...ref.replaceAll(" ", "")];
  let ps = 0;
  let rs = 0;
  for (let n = 1; n <= maxN; n++) {
    const [m, t] = ngramStats(h, r, n);
    const tr = ngramStats(r, r, n)[1];
    ps += t ? m / t : 0;
    rs += tr ? m / tr : 0;
  }
  const p = ps / maxN;
  const rc = rs / maxN;
  return p + rc === 0 ? 0 : ((1 + beta ** 2) * p * rc) / (beta ** 2 * p + rc);
}

function termScore(hyp: string, groups: string[][]): number {
  // 꼭 있어야 할 낱말 묶음 가운데 번역에 들어 있는 비율(묶음마다 하나라도 있으면 통과)
  return groups.filter((g) => g.some((w) => hyp.toLowerCase().includes(w))).length / groups.length;
}

const REF = "I want to go to the dentist tomorrow";
const HYPS: Record<string, string> = { 완벽: REF, "용어 오류(내일 → 어제)": "I want to go to the dentist yesterday", "맞는 바꿔 말하기": "I would like to visit a dentist tomorrow" };
const TERMS = [["tomorrow"], ["dentist"]];
console.log("번역 | BLEU | chrF | 용어");
const S: Record<string, number[]> = {};
for (const [name, hyp] of Object.entries(HYPS)) {
  S[name] = [bleu(hyp, REF), chrf(hyp, REF), termScore(hyp, TERMS)];
  console.log(`${name} | ${S[name][0].toFixed(2)} | ${S[name][1].toFixed(2)} | ${S[name][2].toFixed(2)}`);
}
check(
  Math.abs(brevityPenalty(5, 10) - Math.exp(-1)) < 1e-9 &&
    brevityPenalty(10, 10) === 1 &&
    brevityPenalty(12, 10) === 1 &&
    ngramStats("the cat sat".split(" "), "the cat sat on the mat".split(" "), 1).join() === "3,3" &&
    Math.abs(S["완벽"][0] - 1) < 1e-9 &&
    Math.abs(S["완벽"][1] - 1) < 1e-9 &&
    S["용어 오류(내일 → 어제)"][0] > 0.6 &&
    S["용어 오류(내일 → 어제)"][2] === 0.5 &&
    S["맞는 바꿔 말하기"][0] < 0.4 &&
    S["맞는 바꿔 말하기"][2] === 1,
  "BLEU는 용어 하나가 틀려도 높고, 맞는 바꿔 말하기에는 낮아요. 그래서 용어 정확도를 따로 재야 해요.",
);

order.typescript:
// D38 · Part 3 · 어순과 통역: 동사를 기다려야 한다 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d38_order.ts   (소리·데이터는 코드 안에서 합성해요)
//   한국어(동사가 끝)와 영어(동사가 둘째)의 정렬로 기다려야 하는 낱말 수 재기


function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}


// [대체] 번역 모델 대신 '역할 사전' 번역기: 한국어 덩어리마다 (역할, 영어)를 찾아 영어 어순(주어 동사 목적어 장소 시간)으로 다시 늘어놓는다
const LEX: Record<string, [string, string]> = {
  저는: ["S", "I"],
  내일: ["T", "tomorrow"],
  어제: ["T", "yesterday"],
  "다음 주": ["T", "next week"],
  치과에: ["P", "to the dentist"],
  병원에서: ["P", "at the hospital"],
  스케일링을: ["O", "scaling"],
  "가고 싶어요": ["V", "want to go"],
  "받고 싶어요": ["V", "want to get"],
  "사랑니를 뽑았어요": ["V", "had my wisdom tooth pulled"],
};
const EN_ORDER = "SVOPT"; // 영어 어순: 주어(S) 동사(V) 목적어(O) 장소(P) 시간(T)
const SENTS: string[][] = [
  ["저는", "내일", "치과에", "가고 싶어요"],
  ["저는", "어제", "병원에서", "사랑니를 뽑았어요"],
  ["저는", "다음 주", "스케일링을", "받고 싶어요"],
];

function translate(tokens: string[]): string {
  // 덩어리 목록(앞부분만 들어도 됨) → 영어 문장. 아직 못 들은 덩어리는 빠진다
  return tokens
    .map((t) => LEX[t])
    .sort((a, b) => EN_ORDER.indexOf(a[0]) - EN_ORDER.indexOf(b[0]))
    .map((p) => p[1])
    .join(" ");
}


function inversions(seq: number[]): number {
  // 뒤집힌 짝의 수: 정렬에서 서로 엇갈리는 (앞, 뒤) 쌍
  let c = 0;
  for (let i = 0; i < seq.length; i++) for (let j = i + 1; j < seq.length; j++) if (seq[i] > seq[j]) c++;
  return c;
}

function need(srcOfTgt: number[]): number[] {
  // 목표 덩어리를 차례로 내보낼 때, 각각 원문을 몇 덩어리까지 들어야 하나(앞에서 이미 들은 만큼은 유지)
  let m = 0;
  return srcOfTgt.map((i) => (m = Math.max(m, i + 1)));
}

function koToEn(tokens: string[]): number[] {
  // 영어로 내보내는 순서에서 각 덩어리의 한국어 위치
  return tokens.map((_, i) => i).sort((a, b) => EN_ORDER.indexOf(LEX[tokens[a]][0]) - EN_ORDER.indexOf(LEX[tokens[b]][0]));
}

function meanLag(srcOfTgt: number[]): number {
  // 목표 덩어리 j를 말할 때 그 시각에 '이미 말한 양'보다 원문을 몇 덩어리 더 들어야 하나의 평균
  const n = need(srcOfTgt);
  return n.reduce((s, v, j) => s + (v - (j + 1)), 0) / n.length;
}

for (const s of SENTS) {
  const order = koToEn(s);
  console.log(`${s.join(" ")}\n   영어 순서로 읽는 한국어 위치 [${order}] · 필요한 원문 덩어리 [${need(order)}] · 평균 기다림 ${meanLag(order).toFixed(2)}덩어리 · 뒤집힌 짝 ${inversions(order)}개`);
}
const same = [0, 1, 2, 3]; // 어순이 같은 언어 쌍(예: 영어 ↔ 스페인어): 차례대로 옮기면 된다
console.log(`어순이 같은 쌍: 필요한 원문 덩어리 [${need(same)}] · 평균 기다림 ${meanLag(same).toFixed(2)}덩어리`);
const verbPos = SENTS.map((s) => koToEn(s).indexOf(s.length - 1)); // 한국어 동사(맨 끝)가 영어 순서에서 몇 번째로 나가나
check(
  inversions([0, 3, 2, 1]) === 3 &&
    need([0, 3, 2, 1]).join() === "1,4,4,4" &&
    meanLag(same) === 0 &&
    SENTS.every((s) => meanLag(koToEn(s)) > 0) &&
    SENTS.every((s, k) => verbPos[k] === 1 && need(koToEn(s))[1] === s.length),
  "영어는 동사가 둘째로 나가는데 한국어 동사는 맨 끝이라, 동사를 말하려면 문장이 끝나야 해요.",
);

simul.typescript:
// D38 · Part 3 · 문장 단위 vs 부분 출력 통역 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d38_simul.ts   (소리·데이터는 코드 안에서 합성해요)
//   문장이 끝나길 기다리기 · 낱말마다 다시 번역 · 안정된 앞부분만 확정하기의 지연과 깜빡임


function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}


// [대체] 번역 모델 대신 '역할 사전' 번역기: 한국어 덩어리마다 (역할, 영어)를 찾아 영어 어순(주어 동사 목적어 장소 시간)으로 다시 늘어놓는다
const LEX: Record<string, [string, string]> = {
  저는: ["S", "I"],
  내일: ["T", "tomorrow"],
  어제: ["T", "yesterday"],
  "다음 주": ["T", "next week"],
  치과에: ["P", "to the dentist"],
  병원에서: ["P", "at the hospital"],
  스케일링을: ["O", "scaling"],
  "가고 싶어요": ["V", "want to go"],
  "받고 싶어요": ["V", "want to get"],
  "사랑니를 뽑았어요": ["V", "had my wisdom tooth pulled"],
};
const EN_ORDER = "SVOPT"; // 영어 어순: 주어(S) 동사(V) 목적어(O) 장소(P) 시간(T)
const SENTS: string[][] = [
  ["저는", "내일", "치과에", "가고 싶어요"],
  ["저는", "어제", "병원에서", "사랑니를 뽑았어요"],
  ["저는", "다음 주", "스케일링을", "받고 싶어요"],
];

function translate(tokens: string[]): string {
  // 덩어리 목록(앞부분만 들어도 됨) → 영어 문장. 아직 못 들은 덩어리는 빠진다
  return tokens
    .map((t) => LEX[t])
    .sort((a, b) => EN_ORDER.indexOf(a[0]) - EN_ORDER.indexOf(b[0]))
    .map((p) => p[1])
    .join(" ");
}


const SPEC = 0.6;
const MT_SEC = 0.3; // 덩어리 하나 말하는 시간 · 번역 한 번에 걸리는 시간(초, 가정한 값)

function commonPrefixLen(a: string[], b: string[]): number {
  // 두 번역이 맨 앞부터 똑같은 낱말 수
  let n = 0;
  while (n < Math.min(a.length, b.length) && a[n] === b[n]) n++;
  return n;
}

function run(tokens: string[], policy: string): { first: number | null; flicker: number; final: string[] } {
  // 덩어리를 하나씩 들을 때마다 번역하고, 정책에 따라 화면(shown)을 바꾼다
  let shown: string[] = [];
  let prev: string[] = [];
  let flicker = 0;
  let first: number | null = null;
  for (let k = 1; k <= tokens.length; k++) {
    const t = k * SPEC + MT_SEC;
    const hyp = translate(tokens.slice(0, k)).split(" ");
    const last = k === tokens.length;
    let next: string[];
    if (policy === "sentence") next = last ? hyp : shown; // 문장이 끝나야 번역
    else if (policy === "partial") next = hyp; // 매번 최신 번역으로 바꿔 보여 줌
    else {
      const stable = last ? hyp : hyp.slice(0, commonPrefixLen(prev, hyp)); // 직전 번역과 같은 앞부분만 확정
      next = stable.length > shown.length && stable.slice(0, shown.length).join(" ") === shown.join(" ") ? stable : shown;
    }
    flicker += shown.length - commonPrefixLen(shown, next); // 이미 보여 준 낱말이 바뀐 수
    shown = next;
    prev = hyp;
    if (shown.length && first === null) first = t;
  }
  return { first, flicker, final: shown };
}

const RES: Record<string, { first: number; flicker: number; ok: boolean }> = {};
for (const [policy, name] of [["sentence", "문장 단위"], ["partial", "부분 출력(매번 다시)"], ["stable", "안정된 앞부분만"]]) {
  const r = SENTS.map((s) => run(s, policy));
  RES[policy] = {
    first: r.reduce((a, x) => a + (x.first as number), 0) / r.length,
    flicker: r.reduce((a, x) => a + x.flicker, 0),
    ok: r.every((x, i) => x.final.join(" ") === translate(SENTS[i])),
  };
  console.log(`${name} 첫 낱말이 나오기까지 ${RES[policy].first.toFixed(1)}초 · 깜빡임(바뀐 낱말) ${RES[policy].flicker}개`);
}
check(
  commonPrefixLen(["a", "b", "c"], ["a", "b", "d"]) === 2 &&
    commonPrefixLen(["a"], ["b"]) === 0 &&
    RES.sentence.flicker === 0 &&
    RES.stable.flicker === 0 &&
    RES.partial.flicker > 0 &&
    RES.partial.first < RES.stable.first &&
    RES.stable.first <= RES.sentence.first &&
    Object.values(RES).every((v) => v.ok),
  "부분 출력은 빠르지만 깜빡이고, 문장 단위는 깜빡이지 않지만 느려요. 안정된 앞부분만 확정하면 그 중간이에요.",
);

