}


// [대체] 번역 모델 대신 구절 사전. 앞(한→영)과 뒤(영→한) 사전에 일부러 틀린 항목을 넣어 둔다
const FWD: Record<string, string> = { 하루에: "per week", "한 번": "once", 약을: "the medicine", 먹어요: "take", 식후에: "before meals", 매일: "every day", "두 알": "two pills", 마셔요: "drink", 물을: "water" };
const BWD: Record<string, string> = { "per week": "일주일에", once: "한 번", "the medicine": "약을", take: "먹어요", "before meals": "식후에", "every day": "매일", "two pills": "두 알", drink: "마셔요", water: "물을" };
// 틀린 항목 ① 하루에 → per week (뒤에서 일주일에로 되돌아와 들통남)  ② 식후에 → before meals (뒤에서도 식후에로 돌아와 못 잡음)

const translateWith = (lex: Record<string, string>, phrases: string[]): string[] => phrases.map((p) => lex[p]);

function similarity(a: string[], b: string[]): number {
  // 덩어리 집합의 F1: 원래 말과 되돌린 말이 얼마나 같은가
  const sa = new Set(a);
  const sb = new Set(b);
  const inter = [...sa].filter((x) => sb.has(x)).length;
  return inter === 0 ? 0 : (2 * inter) / (sa.size + sb.size);
}

const CASES: string[][] = [["하루에", "한 번", "약을", "먹어요"], ["매일", "물을", "마셔요"], ["식후에", "약을", "먹어요"], ["매일", "두 알", "먹어요"]];
const TH = 0.8;
const flagged: boolean[] = [];
for (const src of CASES) {
  const en = translateWith(FWD, src);
  const back = translateWith(BWD, en);
  const sim = similarity(src, back);
  flagged.push(sim < TH);
  console.log(`${src.join(" ")} → ${en.join(" ")} → ${back.join(" ")} 유사도 ${sim.toFixed(2)} ${sim < TH ? "확인 필요" : "OK"}`);
}
check(
  flagged.join() === "true,false,false,false" && similarity(["a", "b"], ["a", "b"]) === 1,
  "역번역은 되돌아온 말이 달라진 번역(하루에 → 일주일에)만 잡아요. 앞뒤가 같이 틀린 번역(식후에 → before meals)은 못 잡는다는 한계도 기억하세요.",
);

