# D38 · Part 5 · 정리: 핵심 공식 다시 확인 — 단독 실행 완성 코드 (Python 3.11)
# pip install numpy==2.4.6
# 실행: python d38_recap.py   (소리·데이터는 코드 안에서 합성해요 · 인터넷·GPU·마이크·API 키 불필요)
#   한글 비율 · 짧은 번역 벌점 · 공통 앞부분 · 지연 합 공식을 작은 함수로 확인


import math
import re

import numpy as np


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


import math


def hangul_ratio(text):
    letters = [c for c in text if c.strip()]
    return sum("가" <= c <= "힣" for c in letters) / len(letters) if letters else 0.0


def brevity_penalty(h, r):
    return 1.0 if h >= r else math.exp(1 - r / h)


def common_prefix_len(a, b):
    n = 0
    while n < min(len(a), len(b)) and a[n] == b[n]:
        n += 1
    return n


def pipeline_delay(endpoint, stt, mt, tts):
    return endpoint + stt + mt + tts


quiz = {
    "한글 비율: '안녕 hello' = 2/7": abs(hangul_ratio("안녕 hello") - 2 / 7) < 1e-9,
    "참조보다 같거나 길면 벌점 없음": brevity_penalty(10, 10) == 1.0 and brevity_penalty(12, 10) == 1.0,
    "번역 길이 5, 참조 길이 10 → exp(-1)": abs(brevity_penalty(5, 10) - math.exp(-1)) < 1e-12,
    "공통 앞부분 길이": common_prefix_len(["I", "want", "to"], ["I", "want", "a"]) == 2,
    "지연 = 끝점 + 받아쓰기 + 번역 + 합성": abs(pipeline_delay(0.7, 0.8, 0.5, 0.3) - 2.3) < 1e-12,
}
for q, ok in quiz.items():
    print(("O " if ok else "X ") + q)
check(all(quiz.values()), "틀린 항목(X)을 위 줄에서 찾아 공식을 다시 확인하세요.")

